mapper.update:
update product_edit
set product_edit_title = #{productEditTitle},
product_edit_price = #{productEditPrice},
product_edit_contents = #{productEditContents}
where product_edit_board_idx = #{productEditBoardIdx};

mapper.select:
select  product_edit_img, product_edit_price, product_edit_title, product_edit_contents
from product_edit
where product_edit_board_idx = #{productEditBoardIdx}
